task<int> fetch() {                       // coroutine: returns a pending value
    int v = co_await async_read(...);     // suspends, no thread blocked
    co_return v * 2;
}

void use() {
    auto t = fetch();                     // lazy until awaited
    int v = sync_wait(t);                 // or co_await t inside another coroutine
}

